// 3D model of the right parotid region from Z-Anatomy meshes (CC BY-SA 4.0,
// based on BodyParts3D), plus the great auricular nerve drawn for this app.
// Geometry lives in data/parotid-meshes.js, generated by
// tools/export_zanatomy.py. Coordinates are centimetres centred on the
// parotid gland: +y = superior, +z = anterior, the patient's right side is -x.

window.ANATOMY = window.ANATOMY || { regions: {} };
window.ANATOMY.models = window.ANATOMY.models || {};

window.ANATOMY.models.parotid = {
  // Default view: the right side of the face, as at parotidectomy.
  camera: { target: [0.4, 0.6, 1.2], radius: 26, theta: -1.4, phi: 1.62 },

  // [theta, phi] for the view buttons. The right side faces -x.
  views: {
    lateral: [-Math.PI / 2, Math.PI / 2],
    inferior: [-1.0, 2.6],
    anterior: [-0.05, 1.6]
  },

  look: {
    mandible: { kind: "bone" },
    temporal: { kind: "bone" },
    zygomatic: { kind: "bone" },
    atlas: { kind: "bone" },
    auricle: { kind: "cartilage", color: 0xe7c3b4 },
    masseter: { kind: "muscle", color: 0xa13f3d },
    temporalis: { kind: "muscle", color: 0x9a3c3c },
    pterygoids: { kind: "muscle", color: 0x943a3b },
    scm: { kind: "muscle", color: 0xa4423f },
    digastric_post: { kind: "muscle" },
    stylohyoid: { kind: "muscle", color: 0x9c3a3c },
    stylopharyngeus: { kind: "muscle", color: 0x8f3739 },
    facial_muscles: { kind: "muscle", color: 0xb24c47 },
    platysma: { kind: "muscle", color: 0xc2685a, opacity: 0.35 },
    parotid: { kind: "gland", color: 0xd9a46e },
    parotid_duct: { kind: "duct" },
    smg: { kind: "gland", color: 0xd8a06a },
    eca: { kind: "artery" },
    ica: { kind: "artery" },
    sta: { kind: "artery" },
    transverse_facial: { kind: "artery" },
    maxillary_artery: { kind: "artery" },
    occipital_artery: { kind: "artery" },
    facial_artery: { kind: "artery" },
    retromandibular: { kind: "vein" },
    ejv: { kind: "vein" },
    ijv: { kind: "vein" },
    facial_vein: { kind: "vein" },
    // Facial nerve branches share the nerve colour; the trunk is a touch deeper.
    facial_trunk: { kind: "nerve", color: 0xf2c94c },
    temporal_branch: { kind: "nerve" },
    zygomatic_branch: { kind: "nerve" },
    buccal_branch: { kind: "nerve" },
    mmn: { kind: "nerve" },
    cervical_branch: { kind: "nerve" },
    posterior_auricular_nerve: { kind: "nerve" },
    great_auricular: { kind: "nerve" },
    glossopharyngeal: { kind: "nerve" },
    vagus: { kind: "nerve" },
    accessory: { kind: "nerve" },
    hypoglossal: { kind: "nerve" },
    parotid_nodes: { kind: "node" }
  },

  build(THREE, h) {
    return h.fromMeshes("parotid", this.look);
  }
};
